  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  if (filterType === 'all' || rawLogs.length === 0) {
    return [{ hidden: false, logs: rawLogs }];
  }

  const groups: { type: FilterState; hidden: boolean; logs: T.BuildLog[] }[] = [];

  let currentType: FilterState;
  let currentLogs: T.BuildLog[];
